            ret = TIMER_RETRY;
            return ret;
        }
    }

    timr->it_value = new_setting->it_value;
    if (timr->it_value) {
        timr->it_interval = new_setting->it_interval;
    } else {
        timr->it_interval = 0;
    }

    timr->active = timr->it_value != 0;
    return ret;
}

