    } else {
        timr->active = 1;
    }

    timer_arm(timr);
    return 0;
}

int set_timer_settings(struct k_itimer *timr, int flags, struct itimerspec64 *new_setting, struct itimerspec64 *old_setting) {
    struct itimerspec64 current_setting;

    if (old_setting) {
        old_setting->it_interval.tv_sec = timr->it_interval.tv_sec;
        old_setting->it_interval.tv_nsec = timr->it_interval.tv_nsec;
        old_setting->it_value.tv_sec = timr->it_value.tv_sec;
        old_setting->it_value.tv_nsec = timr->it_value.tv_nsec;
    }

    timr->it_interval.tv_sec = 0;
    timr->it_interval.tv_nsec = 0;

    if (timr->active) {
        if (cancel_timer(timr)) {
            return TIMER_RETRY;
        }
    }

    timr->it_interval.tv_sec = new_setting->it_interval.tv_sec;
    timr->it_interval.tv_nsec = new_setting->it_interval.tv_nsec;
    timr->it_value.tv_sec = new_setting->it_value.tv_sec;
    timr->it_value.tv_nsec = new_setting->it_value.tv_nsec;

    if (timr->it_value.tv_sec == 0 && timr->it_value.tv_nsec == 0) {
        timr->active = 0;
    } else {
        arm_timer(timr);
        timr->active = 1;
    }

    return 0;
}

int set_timer_settings(struct k_itimer *timr, int flags, struct itimerspec64 *new_setting, struct itimerspec64 *old_setting) {
    struct itimerspec64 old;

    if (old_setting)
        *old_setting = timr->it_soft;

    timr->it_interval = 0;

    if (timr->active) {
        if (cancel_timer(&timr->active)) {
            return TIMER_RETRY;
        }
    }

    timr->it_soft = *new_setting;

    if (timr->it_soft.it_value.tv_sec == 0 && timr->it_soft.it_value.tv_nsec == 0) {
        timr->it_soft = old;
        timr->it_interval = 0;
        return 0;
    }

    timr->active = add_timer(&timr->it_soft);
    timr->it_interval = timr->it_soft.it_interval;

    return 0;
}
